const items = $input.all();

return items.map(item => {
  const email = item.json;

  const content = [
    email.subject || "",
    email.text || "",
    email.html || ""
  ].join(" ");

  const patterns = {
    emailAddress: /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i,
    phoneNumber: /\b(?:\+1[-.\s]?)?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}\b/,
    socialSecurityNumber: /\b\d{3}-\d{2}-\d{4}\b/,
    creditCardNumber: /\b(?:\d[ -]?){13,19}\b/,
    passwordField: /\b(?:password|passwd|pwd)\s*[:=]\s*\S+/i,
    apiKey: /\b(?:api[_ -]?key|secret[_ -]?key|access[_ -]?token)\s*[:=]\s*\S+/i
  };

  const detectedTypes = Object.entries(patterns)
    .filter(([name, pattern]) => pattern.test(content))
    .map(([name]) => name);

  return {
    json: {
      ...email,
      sensitiveDataDetected: detectedTypes.length > 0,
      sensitiveDataTypes: detectedTypes,
      privacyScanStatus: "PRELIMINARY",
      externalAIAllowed: false
    }
  };
});

const emails = $input.all();

return emails.map(item => {
  const email = item.json;

  // Get email content
  const html = String(email.html || "");
  const text = String(email.text || "");

  const subject = String(
    email.subject ||
    email.Subject ||
    email.headers?.subject ||
    ""
  );

  const content = (subject + " " + text + " " + html)
    .toLowerCase();

  // Extract URLs
  const hrefPattern =
    /href\s*=\s*["']?(https?:\/\/[^\s"'<>]+)/gi;

  const plainPattern =
    /https?:\/\/[^\s"'<>]+/gi;

  const urls = new Set();

  for (const match of html.matchAll(hrefPattern)) {
    urls.add(match[1].replace(/&amp;/g, "&"));
  }

  for (const match of (html + " " + text).matchAll(plainPattern)) {
    urls.add(match[0].replace(/&amp;/g, "&"));
  }

  // Detect suspicious language
  const keywords = [
    "urgent",
    "verify your account",
    "password",
    "suspended",
    "account locked",
    "unusual activity",
    "immediately",
    "confirm your identity",
    "security alert",
    "verify your identity",
    "payment failed",
    "click here to verify"
  ];

  const indicators = keywords.filter(word =>
    content.includes(word)
  );

  // Preserve privacy scan results
  const sensitiveDataDetected =
    email.sensitiveDataDetected ?? null;

  const sensitiveDataTypes =
    Array.isArray(email.sensitiveDataTypes)
      ? email.sensitiveDataTypes
      : [];

  const privacyScanStatus =
    email.privacyScanStatus ?? "NOT_ASSESSED";

  return {
    json: {
      messageId: email.id ?? email.messageId ?? null,

      linkCount: urls.size,

      // Save extracted links
      detectedUrls: Array.from(urls),

      suspiciousIndicatorCount: indicators.length,

      // Save matched phrases
      suspiciousKeywords: indicators,

      sensitiveDataDetected,
      sensitiveDataTypes,
      privacyScanStatus,

      externalAIAllowed: false,

      analysisStatus:
        "Pending privacy and threat checks"
    }
  };
});

return $input.all().map(item => {
  const data = item.json;

  const count = Number(data.suspiciousIndicatorCount) || 0;
  const links = Number(data.linkCount) || 0;

  let risk = "Needs Review";

  if (count >= 2) {
    risk = "High";
  } else if (count === 1) {
    risk = "Medium";
  } else if (links === 0) {
    risk = "Low";
  }

  let riskExplanation = "";

  if (count >= 2) {
    riskExplanation =
      `This email triggered ${count} suspicious indicators. ` +
      "Multiple warning signs were detected and the email should be reviewed.";
  } else if (count === 1) {
    riskExplanation =
      "This email triggered one suspicious indicator and should be reviewed.";
  } else if (links === 0) {
    riskExplanation =
      "No suspicious indicators or links were detected by the preliminary checks.";
  } else {
    riskExplanation =
      "Links were detected, but their reputation has not been verified.";
  }

  return {
    json: {
      ...data,
      preliminaryRisk: risk,
      riskExplanation,
      riskAssessmentStatus: "Unverified",
      externalAIAllowed: false
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;

  // Check that the link detector ran
  const hasRequiredFields =
    typeof data.linkCount === "number" &&
    typeof data.suspiciousIndicatorCount === "number";

  // Read the sensitive data scanner results
  const sensitiveDataDetected =
    data.sensitiveDataDetected;

  const sensitiveDataTypes =
    Array.isArray(data.sensitiveDataTypes)
      ? data.sensitiveDataTypes
      : [];

  const privacyScanStatus =
    data.privacyScanStatus ?? "NOT_ASSESSED";

  // Only accept a completed preliminary scan
  const scanCompleted =
    privacyScanStatus === "PRELIMINARY" &&
    typeof sensitiveDataDetected === "boolean";

  // Never permit external AI at this stage
  const externalAIAllowed = false;

  let privacyStatus = "NOT_ASSESSED";

  if (scanCompleted && sensitiveDataDetected) {
    privacyStatus = "SENSITIVE_DATA_DETECTED";
  } else if (scanCompleted) {
    privacyStatus = "PRELIMINARY_CLEAR";
  }

  return {
    json: {
      messageId: data.messageId ?? null,

      linkCount: data.linkCount ?? 0,

      suspiciousIndicatorCount:
        data.suspiciousIndicatorCount ?? 0,

      // Preserve detected URLs
      detectedUrls: Array.isArray(data.detectedUrls)
        ? data.detectedUrls
        : [],

      // Preserve suspicious phrases
      suspiciousKeywords: Array.isArray(data.suspiciousKeywords)
        ? data.suspiciousKeywords
        : [],

      preliminaryRisk:
        data.preliminaryRisk ?? "Needs Review",

      // Preserve risk explanation
      riskExplanation:
        data.riskExplanation ??
        "No detailed risk explanation is available.",

      riskAssessmentStatus:
        data.riskAssessmentStatus ?? "Unverified",

      sensitiveDataDetected:
        scanCompleted ? sensitiveDataDetected : null,

      sensitiveDataTypes,

      privacyScanStatus,

      privacyStatus,

      externalAIAllowed,

      processingStatus: !hasRequiredFields
        ? "Missing detector fields"
        : !scanCompleted
          ? "Privacy scan not completed"
          : sensitiveDataDetected
            ? "Sensitive information detected - external analysis blocked"
            : "Preliminary scan completed - external analysis still blocked"
    }
  };
});

