return $input.all().map((item, idx) => {
  const data = $('Privacy Security Gate').all()[idx]?.json || {};
  const lookup = item.json || {};

  // Read Google Safe Browsing response
  const responseBody = lookup.body ?? lookup;
  const statusCode = Number(lookup.statusCode ?? 0);

  const links = Number(data.linkCount ?? 0);
  const indicators = Number(data.suspiciousIndicatorCount ?? 0);
  const risk = data.preliminaryRisk || "Needs Review";

  const urlCheckRan =
    links > 0 &&
    !lookup.error &&
    statusCode === 200;

  const threatMatches = Array.isArray(responseBody.matches)
    ? responseBody.matches
    : [];

  const threatDetected = threatMatches.length > 0;

  const detectedUrls = Array.isArray(data.detectedUrls)
    ? data.detectedUrls
    : [];

  const suspiciousKeywords = Array.isArray(data.suspiciousKeywords)
    ? data.suspiciousKeywords
    : [];

  const riskExplanation =
    data.riskExplanation ||
    "No detailed risk explanation is available.";

  const sensitiveDetected = data.sensitiveDataDetected === true;

  const sensitiveTypes = Array.isArray(data.sensitiveDataTypes)
    ? data.sensitiveDataTypes
    : [];

  const privacyStatus = data.privacyStatus || "NOT_ASSESSED";
  const privacyScanStatus = data.privacyScanStatus || "NOT_ASSESSED";

  const externalAIAllowed = false;

  const recommendations = [
    "Do not open unexpected links or attachments.",
    "Verify suspicious requests through official websites.",
    "Do not share passwords or sensitive information."
  ];

  if (sensitiveDetected) {
    recommendations.push(
      "Sensitive information was detected. Review before sharing."
    );
  }

  if (risk === "High" || risk === "Medium") {
    recommendations.push(
      "Review this email carefully for possible phishing."
    );
  }

  if (threatDetected) {
    recommendations.push(
      "Google Safe Browsing identified a potential threat. Do not visit the flagged URL."
    );
  } else if (!urlCheckRan && links > 0) {
    recommendations.push(
      "URL reputation could not be verified. Treat links with caution."
    );
  }

  // Report status accurately when there are no URLs
  const verificationStatus = links === 0
    ? "Not required - no URLs detected"
    : !urlCheckRan
      ? "Not completed"
      : threatDetected
        ? "Potential threat identified"
        : "Google Safe Browsing check completed; no known matches";

  const threatIntelligenceStatus = links === 0
    ? "Not required - no URLs detected"
    : urlCheckRan
      ? "Google Safe Browsing checked"
      : "Not checked";

  const urlReputation = links === 0
    ? "Not applicable - no URLs detected"
    : !urlCheckRan
      ? "Not verified"
      : threatDetected
        ? "THREAT MATCHED: " +
          threatMatches.map(m =>
            `${m.threatType || "Unknown threat"} - ${
              m.threat && m.threat.url
                ? m.threat.url
                : "URL not provided"
            }`
          ).join("; ")
        : "No known threats found (not a guarantee of safety)";

  const report = [
    "SENTINELAI SECURITY THREAT REPORT",
    "================================",
    "",
    "EMAIL RISK ASSESSMENT",
    "---------------------",
    `Preliminary Risk: ${risk}`,
    `Links Detected: ${links}`,
    `Suspicious Indicators: ${indicators}`,
    "",
    "WHY THIS EMAIL WAS FLAGGED",
    "--------------------------",
    riskExplanation,
    "",
    "DETECTED URLS",
    "-------------",
    ...(detectedUrls.length > 0
      ? detectedUrls.map((url, index) => `${index + 1}. ${url}`)
      : ["No URLs detected."]),
    "",
    "MATCHED WARNING PHRASES",
    "-----------------------",
    ...(suspiciousKeywords.length > 0
      ? suspiciousKeywords.map(
          (keyword, index) => `${index + 1}. ${keyword}`
        )
      : ["No warning phrases detected."]),
    "",
    `Risk Verification: ${verificationStatus}`,
    "",
    "PRIVACY SECURITY ASSESSMENT",
    "---------------------------",
    `Sensitive Data Detected: ${sensitiveDetected ? "YES" : "NO"}`,
    `Sensitive Data Types: ${sensitiveTypes.join(", ") || "None detected"}`,
    `Privacy Scan Status: ${privacyScanStatus}`,
    `Privacy Status: ${privacyStatus}`,
    "",
    "AI & THREAT INTELLIGENCE",
    "------------------------",
    `External AI Analysis: ${externalAIAllowed ? "Allowed" : "Blocked"}`,
    `Threat Intelligence: ${threatIntelligenceStatus}`,
    `URL Reputation: ${urlReputation}`,
    "",
    "RECOMMENDATIONS",
    "---------------",
    ...recommendations,
    "",
    "IMPORTANT:",
    "This is a preliminary automated security assessment.",
    "Detected URLs are not automatically confirmed to be malicious.",
    "Matched phrases are warning signs, not proof of phishing.",
    "A clean URL reputation result does not guarantee an email is safe.",
    "The privacy scan is not a complete sensitive-data audit.",
    "",
    "Generated by SentinelAI"
  ].join("\n");

  return {
    json: {
      messageId: data.messageId ?? null,
      severity: risk,
      riskExplanation,
      linkCount: links,
      suspiciousIndicatorCount: indicators,
      detectedUrls,
      suspiciousKeywords,
      sensitiveDataDetected: sensitiveDetected,
      sensitiveDataTypes: sensitiveTypes,
      privacyStatus,
      privacyScanStatus,
      externalAIAllowed,
      report,
      urlCheckRan,
      threatDetected,
      threatMatchCount: threatMatches.length,
      reportStatus: "PRELIMINARY"
    }
  };
});
